import sys

def can_jump_brute(nums):
    n = len(nums)
    memo = {}

    def dfs(i):
        if i >= n - 1:
            return True
        if i in memo:
            return memo[i]
        for j in range(i + 1, min(n, i + nums[i] + 1)):
            if dfs(j):
                memo[i] = True
                return True
        memo[i] = False
        return False

    return dfs(0)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print('true' if can_jump_brute(nums) else 'false')

import sys

def can_jump_opt(nums):
    n = len(nums)
    dp = [False] * n
    dp[0] = True
    for i in range(n):
        if not dp[i]:
            continue
        for j in range(i + 1, min(n, i + nums[i] + 1)):
            dp[j] = True
    return dp[-1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print('true' if can_jump_opt(nums) else 'false')

import sys

def can_jump_best(nums):
    reach = 0
    for i, v in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + v)
    return True

